package main

const jsAuthenticity = `
const authenticityLabels={INSUFFICIENT:"資料不足",CONSISTENT_OBSERVATIONS:"觀測一致",CONFLICTING_OBSERVATIONS:"觀測有矛盾",READY_FOR_REVIEW:"待確認參考來源",CONFLICTING_REFERENCE:"參考來源有名稱衝突"};
const authenticityPending=new Map();
function authenticityAction(parent,label,callback,ghost=true){const b=el("button",label,ghost?"ghost":"");b.type="button";b.addEventListener("click",async()=>{if(b.disabled)return;try{await callback();}catch(e){notice(e.message,true);}});parent.append(b);return b;}
function authenticityName(state){return authenticityLabels[state]||state;}
function authenticityCost(parent,title,cost){detailRows(parent,[[title+"總額",cost?.total==null?"未知":cost.total+" USD"],["已知部分",cost?.known_subtotal==null?"尚無金額":cost.known_subtotal+" USD"],["金額覆蓋",(cost?.known_samples||0)+" 筆已知 · "+(cost?.unknown_samples||0)+" 筆未知"]]);}
function authenticityDatasetView(parent,d,title){
 const section=detailSection(parent,title);detailRows(section,[["Provider / Account / Key",[d.scope.selection.provider_id,d.scope.selection.account_id,d.scope.selection.credential_id].join(" / ")],["Model / Group / Endpoint",[d.scope.selection.model_id,d.scope.selection.group||"預設群組",d.scope.selection.endpoint].join(" / ")],["來源",d.scope.origin],["Key 版本",d.scope.credential_version],["Canonical Model",d.scope.canonical_id],["模型對應來源",d.scope.metadata_source],["站方或手動聲明能力",(d.scope.declared_capabilities||[]).join("、")||"尚未提供"],["聲明 Context",d.scope.declared_context_tokens??"尚未提供"],["可用性觀測",d.usable_samples+" 筆成功 · "+d.failed_samples+" 筆失敗"],["本機來源憑據",d.attested_samples+" / "+d.samples.length],["取消／中斷等排除",d.excluded_samples],["工具格式與名稱通過驗證",d.tool_call_samples+" 筆"],["可見 Reasoning",d.visible_reasoning_samples+" 筆"],["觀察到的最大輸入",d.largest_observed_payload_bytes+" bytes；未證明最大 Context"]]);
 const cost=el("details");cost.append(el("summary","原請求成本與未知金額"));authenticityCost(cost,"站方回報",d.provider_reported_cost);authenticityCost(cost,"有效費率估計",d.effective_estimated_cost);authenticityCost(cost,"標價估計",d.nominal_estimated_cost);section.append(cost);
 const samples=el("details");samples.append(el("summary","請求條件、來源與證據識別"));for(const sample of d.samples){const row=el("details");row.append(el("summary",new Date(sample.observed_at).toLocaleString()+" · "+sample.outcome+" · "+sample.proof));detailRows(row,[["證據 ID",sample.id],["來源",sample.source],["回應名稱",sample.response_model||"未提供可用名稱"],["名稱聲明",sample.response_name_status],["站方回報輸入／輸出 Token",String(sample.provider_reported_input_tokens??"未知")+" / "+String(sample.provider_reported_output_tokens??"未知")],["輸出上限",sample.observed_features?.max_output_tokens??"無本機憑據"],["條件 Hash",sample.observed_features?.condition_hash||"無法比較"]]);samples.append(row);}section.append(samples);
}
function authenticityReportContent(box,r){
 detailRows(box,[["觀測結果",authenticityName(r.observation_status)],["模型身份", "仍無法證明 · 低信心"],["套件版本",r.suite_version],["保存時間",new Date(r.observed_at).toLocaleString()],["新增外部 HTTP／推論",r.additional_http_requests+" / "+r.additional_inference_requests],["此分析貨幣成本",r.processing_monetary_cost??"未知；沒有新增供應商請求"],["參考狀態",({MISSING:"尚未確認參考來源",STALE:"參考已失效，需重新審閱",USER_CONFIRMED:"使用者確認來源；未獨立證明身份",UNCONFIRMED_DRAFT:"草稿，尚未確認來源"}[r.reference_status]||r.reference_status)],["相同條件",r.matched_samples+" 筆觀測 · "+r.matched_conditions+" 種請求條件"]]);
 box.append(el("p","這是保存當時的觀測快照；成功、名稱與能力命中均不能證明模型身份。"));
 const findings=detailSection(box,"衝突與判定限制");r.findings.forEach(v=>{const p=el("p",v.reason,v.state==="CONFLICT"?"error":"section-description");findings.append(p);if(v.sample_ids.length)findings.append(el("p","證據："+v.sample_ids.join("、"),"detail-provenance"));});
 authenticityDatasetView(box,r.target,"此連線的實際觀測");if(r.reference)authenticityDatasetView(box,r.reference,"參考來源的實際觀測");
 const limits=el("details");limits.append(el("summary","完整限制與保存資料"));r.limits.forEach(v=>limits.append(el("p",v)));factsView(limits,"完整版本化報告",r);box.append(limits);
}
function authenticityReportDetail(r){const box=modal("模型真實性證據");authenticityReportContent(box,r);}
async function openAuthenticityHistory(m){await modelDetail(myModels.find(x=>key(x)===key(m))||m,"7d","history");const section=$("detail").querySelector("[data-authenticity]");if(section)section.open=true;}
function authenticityReferenceDetail(ref,m){
 const box=modal("真實性參考 Review · v"+ref.version),ticket=detailVersion;let busy=false;
 const state=el("div"),controls=el("div",undefined,"actions"),recovery=el("div");box.append(state,controls,recovery);
 const lock=value=>controls.querySelectorAll("button").forEach(n=>n.disabled=value);
 const load=async()=>{const list=await api("/authenticity/references?"+query(m)+"&id="+encodeURIComponent(ref.id));const latest=list.versions[0];if(!latest)throw Error("參考版本尚未讀取完成");if(detailCurrent(ticket)){ref=latest;render();}};
 const run=async(path,body)=>{if(busy)return;busy=true;lock(true);recovery.replaceChildren();try{await submit(path,body);await load();notice("參考版本操作已保存");}catch(e){if(detailCurrent(ticket)){recovery.replaceChildren(el("p","操作結果尚未確認；先重新讀取已保存版本。","error"));authenticityAction(recovery,"重新讀取參考版本",async()=>{await load();recovery.replaceChildren();});notice(e.message,true);}}finally{busy=false;}};
 const render=()=>{state.replaceChildren();controls.replaceChildren();state.append(el("p",authenticityName(ref.review_status)+(ref.active_id===ref.id?" · 目前參考":" · 尚未設為目前參考")),el("p","來源確認理由："+ref.reason),el("p","請自行核對來源與模型對應。此操作只指定行為參考，身份仍無法證明。"));
 authenticityReportContent(state,ref.comparison);
 if(ref.active_id!==ref.id&&ref.review_status==="READY_FOR_REVIEW")authenticityAction(controls,"確認此來源並啟用參考",()=>run("/authenticity/references/activate",{id:ref.id,expected_active_id:ref.active_id||"",confirm:true}),false);
 if(ref.active_id===ref.id&&ref.activation_action_id)authenticityAction(controls,"Undo 真實性參考",()=>run("/versions/undo",{id:ref.activation_action_id,confirm:true}));
 authenticityAction(controls,"返回模型歷史",()=>openAuthenticityHistory(m));};render();
}
function modelAuthenticity(parent,m,ticket){
 const section=el("details"),summary=el("summary","模型真實性證據"),body=el("div");section.dataset.authenticity="true";section.append(summary,el("p","重用既有流量，分開檢視可用性、能力與身份。分析不會新增外部 HTTP 或推論。","section-description"),body);parent.append(section);
 if(!chatOperation(targetOperation(m))){body.append(el("p","目前套件支援文字對話操作；此連線的原始請求紀錄仍保留。","section-description"));return;}
 let loaded=false,reading=false,writing=false,reportOffset=0,referenceOffset=0;
 const pendingKey=key(m),current=()=>detailCurrent(ticket),recovery=el("div"),content=el("div"),commands=el("div",undefined,"actions");body.append(commands,recovery,content);
 const previousDisabled=new Map(),setBusy=value=>{body.setAttribute("aria-busy",String(value));if(value){body.querySelectorAll("input,select,textarea,button").forEach(n=>{if(!previousDisabled.has(n))previousDisabled.set(n,n.disabled);n.disabled=true;});}else{previousDisabled.forEach((disabled,n)=>{if(n.isConnected)n.disabled=disabled;});previousDisabled.clear();}};
 const read=async()=>{if(reading)return;reading=true;setBusy(true);try{const [reports,references]=await Promise.all([api("/authenticity/reports?"+query(m)+"&limit=20&offset="+reportOffset),api("/authenticity/references?"+query(m)+"&limit=20&offset="+referenceOffset)]);if(!current())return;content.replaceChildren();commands.replaceChildren();recovery.replaceChildren();loaded=true;
 authenticityAction(commands,"分析既有請求紀錄",()=>write("analysis"),false);authenticityAction(commands,"更新真實性紀錄",read);
 const reportList=detailSection(content,"分析紀錄");if(!reports.length)reportList.append(el("p","尚無分析紀錄；只有成功的 Reply OK 也不足以證明身份。"));for(const r of reports)item(reportList,authenticityName(r.observation_status)+" · 身份未證明",new Date(r.observed_at).toLocaleString()+" · "+r.target.usable_samples+" 筆成功 · 新增 0 次 HTTP",()=>authenticityReportDetail(r));
 const reportPages=el("div",undefined,"actions");reportList.append(reportPages);if(reportOffset)authenticityAction(reportPages,"較新的分析",()=>{reportOffset=Math.max(0,reportOffset-20);return read();});if(reports.length===20)authenticityAction(reportPages,"較舊的分析",()=>{reportOffset+=20;return read();});
 const refs=detailSection(content,"參考來源版本","選擇另一 Provider、另一 origin 的同一 Canonical Model。來源由你確認，不自動當作官方身份。"),form=el("form"),label=el("label","參考來源連線"),select=el("select");select.setAttribute("aria-label","參考來源連線");select.required=true;label.append(select);form.append(label);
 const candidates=myModels.filter(v=>v.state==="ACTIVE"&&v.enabled&&v.provider_id!==m.provider_id&&modelCanonical(v)===modelCanonical(m)&&chatOperation(targetOperation(v)));for(const v of candidates)option(select,key(v),(providers.find(p=>p.id===v.provider_id)?.name||v.provider_id)+" · "+connectionLabel(v));
 const reason=field(form,"確認參考來源的理由","textarea");reason.required=true;reason.maxLength=1000;const preview=el("button","建立參考版本 Review");preview.disabled=!candidates.length;form.append(preview);refs.append(form);if(!candidates.length)refs.append(el("p","先加入另一來源的同一 Canonical Model 並保留實際流量；本頁不會替你發送測試請求。"));
 form.addEventListener("submit",e=>{e.preventDefault();if(select.value)write("reference",{reference:JSON.parse(select.value),reason:reason.value});});
 for(const ref of references.versions)item(refs,"參考 v"+ref.version+" · "+authenticityName(ref.review_status)+(ref.id===references.active_id?" · 目前參考":""),new Date(ref.created_at).toLocaleString()+" · "+ref.reference.scope.origin,()=>authenticityReferenceDetail(ref,m));
 if(references.active_id&&!references.versions.some(v=>v.id===references.active_id))authenticityAction(refs,"檢視目前參考版本",async()=>{const result=await api("/authenticity/references?"+query(m)+"&id="+encodeURIComponent(references.active_id));if(current()&&result.versions[0])authenticityReferenceDetail(result.versions[0],m);});
 const refPages=el("div",undefined,"actions");refs.append(refPages);if(referenceOffset)authenticityAction(refPages,"較新的參考版本",()=>{referenceOffset=Math.max(0,referenceOffset-20);return read();});if(references.has_more)authenticityAction(refPages,"較舊的參考版本",()=>{referenceOffset+=20;return read();});
 if(references.active_id&&references.activation_action_id)authenticityAction(refs,"Undo 目前真實性參考",()=>write("undo",{id:references.activation_action_id,confirm:true}));
 }catch(e){if(current()){recovery.replaceChildren(el("p","紀錄尚未更新，保留上次內容。","error"));authenticityAction(recovery,"重新讀取真實性紀錄",read);notice(e.message,true);}}finally{reading=false;if(current())setBusy(writing||authenticityPending.has(pendingKey));}};
 const recover=()=>{if(!current())return;setBusy(true);recovery.replaceChildren(el("p","先讀取已保存的操作結果，避免重複提交。","error"));authenticityAction(recovery,"讀取真實性操作結果",async()=>{const pending=authenticityPending.get(pendingKey);if(!pending)return;if(pending.kind==="analysis"){const reports=await api("/authenticity/reports?"+query(m)+"&id="+encodeURIComponent(pending.request.id));if(!reports.length)throw Error("尚無保存結果，請以相同請求重試");}else if(pending.kind==="reference"){const refs=await api("/authenticity/references?"+query(m)+"&id="+encodeURIComponent(pending.request.id));if(!refs.versions.length)throw Error("尚無保存結果，請以相同請求重試");}authenticityPending.delete(pendingKey);await read();});const p=authenticityPending.get(pendingKey);if(p&&p.kind!=="undo"&&!p.ack)authenticityAction(recovery,"以相同識別重試",()=>send(p));};
 const send=async pending=>{if(writing)return;writing=true;setBusy(true);try{await submit(pending.path,pending.request);pending.ack=true;writing=false;await read();if(current()&&loaded&&!recovery.children.length){authenticityPending.delete(pendingKey);setBusy(false);}else recover();}catch(e){writing=false;if(current()){recover();notice(e.message,true);}}};
 const write=async(kind,extra={})=>{if(reading||writing||authenticityPending.has(pendingKey))return;const id=crypto.randomUUID(),request=kind==="analysis"?{id,selection:JSON.parse(key(m))}:kind==="reference"?{id,target:JSON.parse(key(m)),...extra}:extra,path=kind==="analysis"?"/authenticity/analyze":kind==="reference"?"/authenticity/references/preview":"/versions/undo",pending={kind,request,path,ack:false};authenticityPending.set(pendingKey,pending);await send(pending);};
 section.addEventListener("toggle",()=>{if(section.open&&!loaded){read().then(()=>{if(authenticityPending.has(pendingKey))recover();});}});
}
`
